const esc = (v) => {const value=(v&&typeof v==='object')?(typeof v.username==='string'?v.username:'VEXORA Trader'):String(v??'');return value.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))};
function displayName(v){const s=typeof v==='string'?v:(v&&typeof v.username==='string'?v.username:'');return !s.trim()||s.trim()==='[object Object]'?'VEXORA Trader':s.trim()}
function avatarMarkup(name,url=''){const safe=displayName(name);return url?`<img class="avatar avatar-image" src="${esc(url)}" alt="${esc(safe)} avatar" loading="lazy" onerror="this.outerHTML='${esc(safe.charAt(0).toUpperCase())}'">`:`<div class="avatar">${esc(safe.charAt(0).toUpperCase())}</div>`}
function linkify(v){return esc(v).replace(/(https?:\/\/[^\s<]+|www\.[^\s<]+)/gi, raw=>{const clean=raw.replace(/[),.!?;:]+$/,'');const tail=raw.slice(clean.length);const href=clean.toLowerCase().startsWith('www.')?'https://'+clean:clean;return `<a href="${href}" target="_blank" rel="noopener noreferrer nofollow">${clean}</a>${tail}`}).replace(/\n/g,'<br>')}
function renderMessageBody(body){const value=String(body||'');const v=value.match(/^\[\[voice-note:(\/static\/voice_notes\/[A-Za-z0-9_.-]+)\]\]$/);if(v)return `<audio controls preload="none" src="${v[1]}">Voice note</audio>`;const m=value.match(/^\[\[media:(image|video):(\/static\/uploads\/[A-Za-z0-9_.-]+)\]\]$/);if(m)return m[1]==='image'?`<a href="${m[2]}" target="_blank" rel="noopener noreferrer"><img class="message-media-image" loading="lazy" src="${m[2]}" alt="Shared image"></a>`:`<video class="message-media-video" controls preload="metadata" src="${m[2]}"></video>`;return linkify(value)}
function toast(msg){const t=$('#toast');t.textContent=msg;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',3000)}
async function api(path, opts={}) {
  const headers = {'Content-Type':'application/json', ...(opts.headers||{})};
  if (opts.method && opts.method !== 'GET' && csrf) headers['X-CSRF-Token']=csrf;
  const res = await fetch(path,{...opts,headers,credentials:'same-origin'});
  let data={}; try{data=await res.json()}catch{}
  if(!res.ok) throw new Error(data.error||data.detail||'Something went wrong.');
  if(data.csrf) csrf=data.csrf;
  return data;
}
async function refreshAdminNav(){if(!currentUser){$('#adminNav')?.classList.add('hidden');return}try{const p=await api('/api/trades/permissions');$('#adminNav')?.classList.toggle('hidden',!p.can_publish)}catch{$('#adminNav')?.classList.add('hidden')}}
