async function loadTurnstile(){if(window.turnstile)return; if(!turnstileLoadPromise)turnstileLoadPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.async=true;script.defer=true;script.onload=resolve;script.onerror=()=>reject(new Error('Could not load the bot-check. Check your connection and try again.'));document.head.appendChild(script)});await turnstileLoadPromise}
async function renderTurnstile(){const holder=$('#turnstileWidget');if(!holder)return;captchaToken='';try{const cfg=await api('/api/auth/captcha-config');captchaSiteKey=cfg.site_key||'';if(!captchaSiteKey){holder.innerHTML='<p class="message">Bot protection is not configured yet. Please contact the site administrator.</p>';$('#authSubmit').disabled=true;return}$('#authSubmit').disabled=false;await loadTurnstile();turnstileWidgetId=window.turnstile.render(holder,{sitekey:captchaSiteKey,theme:'auto',callback:token=>{captchaToken=token},'expired-callback':()=>{captchaToken=''},'error-callback':()=>{captchaToken=''}})}catch(e){holder.textContent='Bot check could not load. Please refresh and try again.';$('#authSubmit').disabled=true}}
function b64urlToBytes(value){const pad='='.repeat((4-value.length%4)%4);const raw=atob((value+pad).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
function bytesToB64url(value){return btoa(String.fromCharCode(...new Uint8Array(value))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function credentialJSON(cred){const out={id:cred.id,rawId:bytesToB64url(cred.rawId),type:cred.type,clientExtensionResults:cred.getClientExtensionResults(),response:{}};for(const key of ['clientDataJSON','attestationObject','authenticatorData','signature','userHandle'])if(cred.response[key])out.response[key]=bytesToB64url(cred.response[key]);return out}
async function runPasskeyLogin(){const email=$('#authEmail')?.value.trim().toLowerCase();if(!email){toast('Enter your account email first.');return}if(!window.PublicKeyCredential||!navigator.credentials){toast('This browser does not support passkeys.');return}try{const opts=await api('/api/passkeys/login/options',{method:'POST',body:JSON.stringify({email})});opts.challenge=b64urlToBytes(opts.challenge);if(opts.allowCredentials)opts.allowCredentials=opts.allowCredentials.map(x=>({...x,id:b64urlToBytes(x.id)}));const cred=await navigator.credentials.get({publicKey:opts});const data=await api('/api/passkeys/login/verify',{method:'POST',body:JSON.stringify(credentialJSON(cred))});currentUser=data.user;csrf=data.csrf;closeAuth();accountArea();startPresenceHeartbeat();refreshAdminNav();toast('Welcome back, '+currentUser.username+'!');render()}catch(e){toast(e.message||'Passkey sign-in was cancelled or failed.')}}
async function runPasswordReset(){const email=prompt('Enter the email address on your VEXORA account:');if(!email)return;try{const sent=await api('/api/auth/password-reset/request',{method:'POST',body:JSON.stringify({email})});let code=sent.development_code||'';if(!code)code=prompt(sent.message+' Enter the 6-digit code from your email:')||'';else toast('Development reset code: '+code);if(!code)return;const password=prompt('Enter a new password (12 characters minimum):');if(!password)return;const confirm=prompt('Confirm the new password:');if(password!==confirm){toast('Passwords do not match.');return}const result=await api('/api/auth/password-reset/complete',{method:'POST',body:JSON.stringify({email,code,password})});csrf=result.csrf||csrf;toast(result.message)}catch(e){toast(e.message)}}
function openAuth(mode='login'){authMode=mode;signupStage='email';signupEmail='';$('#modal').classList.remove('hidden');$('#authMessage').textContent='';setAuthMode(mode)}
