function setAuthMode(mode){authMode=mode;signupStage='email';signupEmail='';document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('selected',b.dataset.auth===mode));$('#modalTitle').textContent=mode==='login'?'Welcome back to VEXORA':'Join VEXORA';$('#authMessage').textContent='';renderAuthFields()}
