$('#authForm').addEventListener('submit',async e=>{
 e.preventDefault();const msg=$('#authMessage');msg.textContent='Working…';msg.className='message';
 try{
  if(authMode==='login'){
   const data=await api('/api/login',{method:'POST',body:JSON.stringify({email:$('#authEmail').value,password:$('#authPassword').value})});currentUser=data.user;csrf=data.csrf;closeAuth();accountArea();startPresenceHeartbeat();refreshAdminNav();toast('Welcome back, '+currentUser.username+'!');render();return;
  }
  if(signupStage==='email'){
   signupEmail=$('#signupEmail').value.trim().toLowerCase();signupLanguage=$('#signupLanguage').value;const d=await api('/api/auth/request-code',{method:'POST',body:JSON.stringify({email:signupEmail,language:signupLanguage})});signupStage='code';renderAuthFields();msg.textContent=d.development_code?'DEV TEST CODE: '+d.development_code+' (email provider not configured)':'Verification code sent. Check your email.';msg.className='message success';return;
  }
  if(signupStage==='code'){
   await api('/api/auth/verify-code',{method:'POST',body:JSON.stringify({email:signupEmail,code:$('#signupCode').value.trim()})});signupStage='password';renderAuthFields();msg.textContent='Email verified. Create your account details.';msg.className='message success';return;
  }
  const username=$('#signupUsername').value.trim();const password=$('#signupPassword').value;const confirm_password=$('#signupConfirm').value;
  if(password!==confirm_password){throw new Error('Passwords do not match.')}if(!captchaToken){throw new Error("Please complete the I'm not a robot check.")}const data=await api('/api/auth/complete-signup',{method:'POST',body:JSON.stringify({username,password,confirm_password,captcha_token:captchaToken})});currentUser=data.user;csrf=data.csrf;closeAuth();accountArea();startPresenceHeartbeat();refreshAdminNav();toast('Welcome to VEXORA, '+currentUser.username+'!');render();
 }catch(err){msg.textContent=err.message;msg.className='message'}
});
